"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";

/*
 * World Map Continental — the whole world on a 540 × 242 grid, with one continent lifted out of it.
 * The land is the same quiet grey everywhere; the chosen continent is repainted white with a soft
 * shadow, and a pastel band travels around its coastline on a fourteen-second loop. Picking another
 * continent in the corner menu cross-fades the two: the old highlight fades while the new one
 * settles in from slightly smaller, growing out of that continent's own centre of mass.
 *
 * The pill itself is the other half of the idea. Closed, it is a rounded button; opening it morphs
 * the menu out of the button's measured size (a clip-path inset on both axes) while the rows fade
 * up. The grey selection fill glides between rows. The whole cluster scales down with the
 * illustration so it still fits when the map is small.
 */

export type Continent = "north-america" | "south-america" | "europe" | "africa" | "asia" | "oceania";

export type WorldMapProps = {
  /** The continent to light up, when the parent owns the choice */
  continent?: Continent;
  /** Continent highlighted on first render, when `continent` is not given */
  defaultContinent?: Continent;
  /** Called with the continent the viewer picks in the corner menu */
  onContinentChange?: (continent: Continent) => void;
  /** Show the continent menu in the top-left corner of the map */
  showSwitcher?: boolean;
  /** Accessible name for the drawing; by default it names the highlighted continent */
  label?: string | ((continent: Continent) => string);
  className?: string;
};

const CONTINENTS: { value: Continent; name: string }[] = [
  { value: "north-america", name: "North America" },
  { value: "south-america", name: "South America" },
  { value: "europe", name: "Europe" },
  { value: "africa", name: "Africa" },
  { value: "asia", name: "Asia" },
  { value: "oceania", name: "Oceania" },
];

type Phase = "idle" | "enter" | "exit";

type Shape = {
  /** Where the highlight grows from — the centre of the continent's mainland, in viewBox units */
  origin: string;
  /** Every ring, islands included: the shape that gets lifted, and the hole that keeps the glow at sea */
  land: string;
};

/**
 * A continent's path draws its mainland first, then its islands. The band runs along that first
 * ring only, so it traces one coast instead of hopping between archipelagos.
 */
const coastOf = (land: string) => land.slice(0, land.indexOf("z") + 1);

