/* useLayoutEffect measures before the first paint; on the server it simply never runs */
const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export function WorldMap({
  continent,
  defaultContinent = "europe",
  onContinentChange,
  showSwitcher = true,
  label,
  className,
}: WorldMapProps) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const root = useRef<HTMLDivElement>(null);
  const [own, setOwn] = useState<Continent>(defaultContinent);
  const current = continent ?? own;
  const name = CONTINENTS.find((option) => option.value === current)?.name ?? "Europe";

  /* One layer per continent on screen: the settled highlight, plus whatever is still fading out */
  const [layers, setLayers] = useState<{ key: number; continent: Continent; phase: Phase }[]>(() => [
    { key: 0, continent: current, phase: "idle" },
  ]);

  useEffect(() => {
    setLayers((all) => {
      if (all[all.length - 1].continent === current) return all;
      const next = all.reduce((highest, layer) => Math.max(highest, layer.key), 0) + 1;
      return [
        ...all.map((layer) => ({ ...layer, phase: "exit" as Phase })),
        { key: next, continent: current, phase: "enter" as Phase },
      ];
    });
  }, [current]);

  useEffect(() => {
    if (!layers.some((layer) => layer.phase !== "idle")) return;
    const timer = setTimeout(() => {
      setLayers((all) =>
        all.filter((layer) => layer.phase !== "exit").map((layer) => ({ ...layer, phase: "idle" as Phase })),
      );
    }, 560);
    return () => clearTimeout(timer);
  }, [layers]);

  /* The corner menu is drawn at 540 px wide and shrinks with the illustration */
  const [scale, setScale] = useState(1);
  useIsoLayoutEffect(() => {
    const el = root.current;
    if (!el) return;
    const fit = () => {
      const width = el.getBoundingClientRect().width;
      if (width > 0) setScale(Math.min(1, width / 580));
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={root}
      className={["ui-wm", className].filter(Boolean).join(" ")}
      style={{ "--ui-wm-s": scale } as CSSProperties}
    >
      {/* React 19 hoists this into <head> once, no matter how many maps render */}
      <style href="ui-world-map" precedence="default">
        {css}
      </style>

      <div
        className="ui-wm-map"
        role="img"
        aria-label={typeof label === "function" ? label(current) : (label ?? `World map with ${name} highlighted`)}
      >
        <svg className="ui-wm-art" viewBox="0 0 540 242" aria-hidden="true">
          <defs>
            {/* Shadow under the lifted continent — `.ui-wm-drop` recolours it in dark mode */}
            <filter id={`ui-wm${uid}-shadow`} x="-15%" y="-15%" width="130%" height="130%">
              <feDropShadow
                className="ui-wm-drop"
                dx="0"
                dy="2"
                stdDeviation="2.5"
                floodColor="#1F2128"
                floodOpacity="0.1"
              />
            </filter>
            {/* The pastel the band is painted with, left to right across the map */}
            <linearGradient id={`ui-wm${uid}-shine`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="540" y2="242">
              <stop offset="0%" stopColor="#FFA0AB" />
              <stop offset="33%" stopColor="#FFB89E" />
              <stop offset="66%" stopColor="#C8A8E5" />
              <stop offset="100%" stopColor="#A8B5FF" />
            </linearGradient>
            <filter id={`ui-wm${uid}-blur`} x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="4" />
            </filter>
          </defs>

          {/* The quiet world underneath: every continent, always the same */}
          <g className="ui-wm-land" fill="#E8E8E8" stroke="#E8E8E8" strokeWidth="0.5" strokeLinejoin="round">
            {CONTINENTS.map((option) => (
              <path key={option.value} d={SHAPES[option.value].land} />
            ))}
          </g>

          {layers.map((layer) => (
            <Layer key={layer.key} uid={uid} index={layer.key} shape={SHAPES[layer.continent]} phase={layer.phase} />
          ))}
        </svg>
      </div>

      {showSwitcher && (
        <Switcher
          value={current}
          name={name}
          onSelect={(next) => {
            if (continent === undefined) setOwn(next);
            if (next !== current) onContinentChange?.(next);
          }}
        />
      )}
    </div>
  );
}

/* ---------- One continent lifted out of the world, with a band along its coast ---------- */

function Layer({ uid, index, shape, phase }: { uid: string; index: number; shape: Shape; phase: Phase }) {
  const outside = `ui-wm${uid}-${index}-outside`;
  const coast = coastOf(shape.land);

  return (
    <g className="ui-wm-layer" data-phase={phase} style={{ transformOrigin: shape.origin }}>
      <defs>
        {/* The band glows outwards only: the land itself punches a hole in the mask */}
        <mask id={outside} maskUnits="userSpaceOnUse" x="0" y="0" width="540" height="242">
          <rect x="0" y="0" width="540" height="242" fill="#FFFFFF" />
          <path d={shape.land} fill="#000000" />
        </mask>
      </defs>

      <path
        className="ui-wm-focus"
        d={shape.land}
        filter={`url(#ui-wm${uid}-shadow)`}
        fill="#FFFFFF"
        stroke="#E2E2E2"
        strokeWidth="0.5"
        strokeLinejoin="round"
      />

      <g fill="none" stroke={`url(#ui-wm${uid}-shine)`} strokeLinecap="round" strokeLinejoin="round">
        <path
          className="ui-wm-band"
          d={coast}
          pathLength={1000}
          strokeWidth="6"
          strokeDasharray="180 820"
          filter={`url(#ui-wm${uid}-blur)`}
          mask={`url(#${outside})`}
          opacity="0.45"
        />
        <path
          className="ui-wm-band"
          d={coast}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="200 800"
          opacity="0.32"
        />
        <path
          className="ui-wm-band ui-wm-band--1"
          d={coast}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="140 860"
          strokeDashoffset={-30}
          opacity="0.55"
        />
        <path
          className="ui-wm-band ui-wm-band--2"
          d={coast}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="80 920"
          strokeDashoffset={-60}
        />
      </g>
    </g>
  );
}

/* ---------- Continent menu: a pill that morphs open into a listbox ---------- */

function Switcher({
  value,
  name,
  onSelect,
}: {
  value: Continent;
  name: string;
  onSelect: (continent: Continent) => void;
}) {
  /* A second id, so the option ids never collide with the per-layer mask ids */
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const listId = `ui-wm-menu${uid}-list`;
  const optionId = (index: number) => `ui-wm-menu${uid}-${index}`;

  const trigger = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const panel = useRef<HTMLDivElement>(null);

  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [glide, setGlide] = useState(false);
  /* The clip-path morph starts from the button's own size, so it is measured rather than guessed */
  const [from, setFrom] = useState({ width: 84, height: 28 });

  useIsoLayoutEffect(() => {
    const el = trigger.current;
    if (!el) return;
    const read = () => setFrom({ width: el.offsetWidth, height: el.offsetHeight });
    read();
    const observer = new ResizeObserver(read);
    observer.observe(el);
    return () => observer.disconnect();
  }, [name]);

  /* Opening starts on the current choice, and hands the keyboard to the listbox */
  useEffect(() => {
    if (!open) return;
    const index = CONTINENTS.findIndex((option) => option.value === value);
    setActive(index < 0 ? 0 : index);
    const frame = requestAnimationFrame(() => panel.current?.focus());
    return () => cancelAnimationFrame(frame);
  }, [open, value]);

  /* The fill appears with the list, then glides for every later move */
  useEffect(() => {
    if (!open) {
      setGlide(false);
      return;
    }
    const timer = setTimeout(() => setGlide(true), 200);
    return () => clearTimeout(timer);
  }, [open]);

  /* A press anywhere outside the pill and the list closes it */
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: globalThis.PointerEvent) => {
      const target = event.target as Node;
      if (menu.current?.contains(target) || trigger.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const close = () => {
    setOpen(false);
    trigger.current?.focus();
  };

  const pick = (index: number) => {
    const option = CONTINENTS[index];
    if (!option) return;
    setActive(index);
    onSelect(option.value);
    close();
  };

  const onTriggerKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setOpen(true);
    }
  };

  const onPanelKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const last = CONTINENTS.length - 1;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setActive((index) => (index >= last ? 0 : index + 1));
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActive((index) => (index <= 0 ? last : index - 1));
    } else if (event.key === "Home") {
      event.preventDefault();
      setActive(0);
    } else if (event.key === "End") {
      event.preventDefault();
      setActive(last);
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pick(active);
    } else if (event.key === "Escape") {
      event.preventDefault();
      close();
    } else if (event.key === "Tab") {
      /* The list goes inert as it closes, so hand focus back before the browser moves on */
      trigger.current?.focus();
      setOpen(false);
    }
  };

  return (
    <div className="ui-wm-switch">
      <button
        ref={trigger}
        type="button"
        className="ui-wm-trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        aria-label={`Continent: ${name}`}
        onClick={() => setOpen((value) => !value)}
        onKeyDown={onTriggerKeyDown}
      >
        <span>{name}</span>
        <svg className="ui-wm-chevron" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path
            d="M18 9.00005C18 9.00005 13.5811 15 12 15C10.4188 15 6 9 6 9"
            className="ui-wm-chevron-ink"
            stroke="#737373"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>

      <div
        ref={menu}
        className="ui-wm-menu"
        data-open={open ? "true" : "false"}
        inert={!open}
        style={
          {
            "--from-w": `${from.width}px`,
            "--from-h": `${from.height}px`,
          } as CSSProperties
        }
      >
        <div
          ref={panel}
          id={listId}
          className="ui-wm-panel"
          role="listbox"
          tabIndex={-1}
          aria-label="Select a continent"
          aria-activedescendant={optionId(active)}
          onKeyDown={onPanelKeyDown}
        >
          <span
            className="ui-wm-fill"
            aria-hidden="true"
            data-glide={glide ? "true" : "false"}
            style={{ transform: `translateY(${5 + 32 * active}px)`, height: 32, opacity: open ? 1 : 0 }}
          />
          {CONTINENTS.map((option, index) => (
            <div
              key={option.value}
              id={optionId(index)}
              role="option"
              aria-selected={option.value === value}
              className="ui-wm-option"
              onPointerEnter={() => setActive(index)}
              onClick={() => pick(index)}
            >
              <span className="ui-wm-option-name">{option.name}</span>
              <span className="ui-wm-check" aria-hidden="true">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.75"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <path d="M5 14L8.5 17.5L19 6.5" />
                </svg>
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ---------- Styles ---------- */

const css = /* css */ `
.ui-wm{--ui-wm-ease: cubic-bezier(0.22, 1, 0.36, 1);position: relative;width: 100%;aspect-ratio: 540 / 242}
.ui-wm-map, .ui-wm-art{position: absolute;inset: 0;display: block;width: 100%;height: 100%}
.ui-wm-band{animation: ui-wm-travel var(--nm-dur-6, 1100ms) linear infinite}
.ui-wm-band--1{animation-delay: -0.42s}
.ui-wm-band--2{animation-delay: -0.84s}
@keyframes ui-wm-travel{from{stroke-dashoffset: 0}
to{stroke-dashoffset: -1000}
}
.ui-wm-layer{transform-box: view-box}
.ui-wm-layer[data-phase="enter"]{animation: ui-wm-in var(--nm-dur-5, 620ms) var(--ui-wm-ease) both}
.ui-wm-layer[data-phase="exit"]{animation: ui-wm-out var(--nm-dur-4, 380ms) cubic-bezier(0.4, 0, 1, 1) both}
@keyframes ui-wm-in{from{opacity: 0;transform: scale(0.94)}
}
@keyframes ui-wm-out{to{opacity: 0}
}
.ui-wm-switch{position: absolute;top: 0;left: 0;z-index: 1;padding: 12px;transform: scale(var(--ui-wm-s, 1));transform-origin: 0 0;font-family: inherit;-webkit-font-smoothing: antialiased}
.ui-wm-trigger{display: flex;align-items: center;gap: 4px;height: 28px;margin: 0;padding: 0 8px 0 12px;border: 1px solid #ded4ca;border-radius: 999px;background: #fffdfb;box-shadow: 0 1px 2px rgba(11, 9, 8, 0.04);color: #1c1713;font: inherit;font-size: 13px;font-weight: 500;line-height: 1;white-space: nowrap;cursor: pointer;transition: transform 160ms var(--ui-wm-ease)}
.ui-wm-trigger:active{transform: scale(0.96)}
.ui-wm-trigger:focus-visible{outline: 2px solid #ffb28f;outline-offset: 2px}
.ui-wm-chevron{width: 14px;height: 14px;transition: transform var(--nm-dur-3, 240ms) var(--ui-wm-ease)}
.ui-wm-trigger[aria-expanded="true"] .ui-wm-chevron{transform: rotate(180deg)}
.ui-wm-menu{--morph: 420ms cubic-bezier(0.32, 0.72, 0, 1);position: absolute;top: calc(12px + 28px + 6px);left: 12px;width: 172px;filter: drop-shadow(0 6px 12px rgba(11, 9, 8, 0.08)) drop-shadow(0 1px 2.5px rgba(11, 9, 8, 0.05));transition: visibility 0s linear 0s}
.ui-wm-menu[data-open="false"]{visibility: hidden;pointer-events: none;transition: visibility 0s linear 300ms}
.ui-wm-panel{position: relative;box-sizing: border-box;display: flex;flex-direction: column;padding: 5px;background: #fffdfb;border: 1px solid #ded4ca;border-radius: 16px;outline: none;clip-path: inset(0 0 0 0 round 16px);transition: clip-path var(--morph)}
.ui-wm-menu[data-open="false"] .ui-wm-panel{clip-path: inset(0 calc(100% - var(--from-w)) calc(100% - var(--from-h)) 0 round calc(var(--from-h) / 2));transition: clip-path var(--nm-dur-3, 240ms) cubic-bezier(0.4, 0, 0.2, 1)}
.ui-wm-panel > *{transition: opacity var(--nm-dur-3, 240ms) ease-out 110ms, transform 380ms var(--ui-wm-ease) 60ms}
.ui-wm-menu[data-open="false"] .ui-wm-panel > *{opacity: 0;transition: opacity var(--nm-dur-1, 90ms) ease-in}
.ui-wm-menu[data-open="false"] .ui-wm-option{transform: translateY(-4px)}
.ui-wm-fill{position: absolute;top: 0;left: 5px;right: 5px;border-radius: 10px;background: #f4ece5;pointer-events: none;transition: transform var(--nm-dur-2, 160ms) cubic-bezier(0.25, 1, 0.3, 1), height var(--nm-dur-2, 160ms) cubic-bezier(0.25, 1, 0.3, 1), opacity 160ms ease-out}
.ui-wm-fill[data-glide="false"]{transition: opacity 160ms ease-out}
.ui-wm-option{position: relative;display: flex;align-items: center;gap: 8px;padding: 7px 8px 7px 10px;border-radius: 10px;color: #1c1713;font-size: 13px;font-weight: 500;line-height: 18px;cursor: pointer}
.ui-wm-option-name{flex: 1;min-width: 0;white-space: nowrap}
.ui-wm-check{flex: none;width: 15px;height: 15px;opacity: 0;transform: scale(0.6);transition: opacity 160ms ease-out, transform var(--nm-dur-3, 240ms) cubic-bezier(0.34, 1.5, 0.64, 1)}
.ui-wm-check svg{display: block;width: 100%;height: 100%}
.ui-wm-option[aria-selected="true"] .ui-wm-check{opacity: 1;transform: none}
@media (prefers-reduced-motion: reduce){.ui-wm-band, .ui-wm-layer{animation: none !important}
.ui-wm-layer[data-phase="exit"]{display: none}
.ui-wm-panel, .ui-wm-panel > *, .ui-wm-fill, .ui-wm-check, .ui-wm-chevron{transition: none !important}
}
:where(.dark, [data-theme="dark"]) .ui-wm-land{fill: #2b231b;stroke: #2b231b}
:where(.dark, [data-theme="dark"]) .ui-wm-focus{fill: #44382b;stroke: rgba(255, 253, 251, 0.12)}
:where(.dark, [data-theme="dark"]) .ui-wm-drop{flood-color: #0b0908;flood-opacity: 0.45}
:where(.dark, [data-theme="dark"]) .ui-wm-trigger{border-color: rgba(255, 253, 251, 0.08);background: #27201a;box-shadow: 0 1px 2px rgba(11, 9, 8, 0.4);color: #ebe3da}
:where(.dark, [data-theme="dark"]) .ui-wm-chevron-ink{stroke: #857567}
:where(.dark, [data-theme="dark"]) .ui-wm-menu{filter: drop-shadow(0 6px 12px rgba(11, 9, 8, 0.4)) drop-shadow(0 1px 2.5px rgba(11, 9, 8, 0.35))}
:where(.dark, [data-theme="dark"]) .ui-wm-panel{background: #27201a;border-color: rgba(255, 253, 251, 0.08)}
:where(.dark, [data-theme="dark"]) .ui-wm-fill{background: #2b231b}
:where(.dark, [data-theme="dark"]) .ui-wm-option{color: #ebe3da}

`;
